package com.gukhan.ainlp.rag;
import com.gukhan.ainlp.document.*;import com.gukhan.ainlp.rbac.RbacService;import com.gukhan.ainlp.user.UserRepository;import java.util.*;import java.util.stream.Collectors;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Service;
@Service public class RagService{private final DocumentChunkRepository docs;private final UserRepository users;private final RbacService rbac;public RagService(DocumentChunkRepository d,UserRepository u,RbacService r){docs=d;users=u;rbac=r;}
public Answer answer(String q){String n=SecurityContextHolder.getContext().getAuthentication().getName();var u=users.findByUsername(n).orElseThrow();var allowed=rbac.departments(u.getRole());var matches=docs.findTop8ByDepartmentIn(allowed).stream().filter(d->contains(d.getText(),q)).limit(5).toList();String a=matches.isEmpty()?"No authorized document context matched the question.":"Authorized context found. Connect this service to Qdrant + Groq for semantic retrieval and generation.";return new Answer(a,matches.stream().map(DocumentChunk::getSource).distinct().collect(Collectors.toList()));}
private boolean contains(String text,String q){String t=text.toLowerCase();return Arrays.stream(q.toLowerCase().split("\\W+")).filter(w->w.length()>2).anyMatch(t::contains);}}